Below is a **complete, self‑contained C++ program** that shows a few of the most common ways you can use templates.  
Feel free to copy‑paste it into a file named `templates_demo.cpp` and compile it with any C++17/20/23 compiler (e.g. `g++ -std=c++20 templates_demo.cpp -o demo`).

```cpp
/*********************************************************************
 *  templates_demo.cpp
 *
 *  A quick, readable illustration of C++ templates.
 *
 *  - A function template (`max`) that works for any comparable type.
 *  - A function template (`swapValues`) that swaps two objects of the
 *    same type.  Note that the swap is implemented *in‑place* by
 *    reference; no copy constructors are invoked.
 *  - A generic container class template (`Pair`) that stores two
 *    values.  The template is written once, but we show a
 *    specialization for `Pair<int, int>` that adds a convenience
 *    method.
 *
 *  Compile:  g++ -std=c++20 templates_demo.cpp -o demo
 *  Run:      ./demo
 *********************************************************************/

#include <iostream>
#include <string>
#include <type_traits>   // for std::is_same

/*********************************************************************
 * 1. Function template: max
 *
 *    Returns the greater of two values.  The compiler generates a
 *    concrete function for every distinct type `T` that appears
 *    in a call to `max<T>`.
 *********************************************************************/
template <typename T>
T max(const T& a, const T& b)
{
    return (a > b) ? a : b;   // uses the `>` operator of type T
}

/*********************************************************************
 * 2. Function template: swapValues
 *
 *    Swaps the contents of two variables of the *same* type.
 *    The function works in place and requires no copy operations
 *    (assuming the type is not a bit‑field or otherwise exotic).
 *********************************************************************/
template <typename T>
void swapValues(T& lhs, T& rhs)
{
    T temp = std::move(lhs);   // move if the type supports it
    lhs = std::move(rhs);
    rhs = std::move(temp);
}

/*********************************************************************
 * 3. Class template: Pair
 *
 *    A simple generic container holding two values, of possibly
 *    different types.  The member functions are all templated on
 *    the same type parameters as the class.
 *********************************************************************/
template <typename T1, typename T2>
class Pair
{
public:
    // Constructors
    Pair() = default;
    Pair(const T1& first, const T2& second)
        : first_(first), second_(second) {}

    // Accessors
    const T1& first() const  { return first_; }
    const T2& second() const { return second_; }

    // Modifiers
    void setFirst(const T1& v)  { first_ = v; }
    void setSecond(const T2& v){ second_ = v; }

    // Print the pair nicely
    void print() const
    {
        std::cout << '(' << first_ << ", " << second_ << ')' << '\n';
    }

private:
    T1 first_;
    T2 second_;
};

/*********************************************************************
 * 4. Full specialization of Pair<int, int>
 *
 *    Adds a convenience method that returns the sum of the two ints.
 *********************************************************************/
template <>
class Pair<int, int>
{
public:
    Pair() = default;
    Pair(int a, int b) : first_(a), second_(b) {}

    int first() const  { return first_; }
    int second() const { return second_; }

    void setFirst(int v)  { first_ = v; }
    void setSecond(int v) { second_ = v; }

    void print() const
    {
        std::cout << '(' << first_ << ", " << second_ << ')' << '\n';
    }

    // Special member: sum of the two ints
    int sum() const { return first_ + second_; }

private:
    int first_;
    int second_;
};

/*********************************************************************
 * 5. Main: Demonstrate all the pieces
 *********************************************************************/
int main()
{
    std::cout << "=== Function template: max ===\n";
    int    i1 = 3, i2 = 7;
    double d1 = 3.14, d2 = 2.718;
    std::string s1 = "alpha", s2 = "beta";

    std::cout << "max(" << i1 << ", " << i2 << ") = " << max(i1, i2) << '\n';
    std::cout << "max(" << d1 << ", " << d2 << ") = " << max(d1, d2) << '\n';
    std::cout << "max(\"" << s1 << "\", \"" << s2 << "\") = \"" << max(s1, s2) << "\"\n";

    std::cout << "\n=== Function template: swapValues ===\n";
    std::cout << "Before swap: i1=" << i1 << ", i2=" << i2 << '\n';
    swapValues(i1, i2);
    std::cout << "After swap:  i1=" << i1 << ", i2=" << i2 << '\n';

    std::cout << "\n=== Class template: Pair<T1,T2> ===\n";
    Pair<std::string, double> p1("pi", 3.14159);
    p1.print();

    Pair<int, int> p2(4, 5);
    p2.print();
    std::cout << "p2.sum() = " << p2.sum() << '\n';

    // Show that the specialized Pair can be used like a normal Pair
    Pair<int, int> p3(10, 20);
    p3.print();
    std::cout << "p3.sum() = " << p3.sum() << '\n';

    // If you want a Pair of different types but you also want the sum,
    // you would need to provide your own method or a different class.
    // That's why specialization is handy when you need a custom interface.

    std::cout << "\n=== Template instantiation details ===\n";
    // The compiler creates concrete functions/classes for the types
    // that we actually use.  For example, a `max<int>` function is
    // generated for the call max(i1, i2), and a `Pair<std::string, double>`
    // class is generated for p1.

    return 0;
}
```

### What the program shows

| Concept | Code snippet | What it demonstrates |
|---------|--------------|----------------------|
| **Function template** (`max`) | `template <typename T> T max(const T& a, const T& b)` | Generates a `max` function for any comparable type. |
| **Function template** (`swapValues`) | `template <typename T> void swapValues(T& lhs, T& rhs)` | Swaps values by reference; no copying. |
| **Class template** (`Pair`) | `template <typename T1, typename T2> class Pair` | Stores two values of potentially different types. |
| **Full specialization** (`Pair<int, int>`) | `template <> class Pair<int, int> { ... }` | Adds a custom member (`sum()`) when both template arguments are `int`. |
| **Instantiation** | `Pair<std::string, double> p1(...)` | The compiler creates a concrete `Pair<std::string, double>` class at compile time. |

You can run the program and observe the output, which confirms that the same generic definitions work seamlessly with `int`, `double`, `std::string`, and even specialized behavior for `Pair<int, int>`. This is the essence of C++ templates: **write once, use for any type (and even for special types with custom behavior).**
